class ExpressionEvaluator:
    """A class to evaluate arithmetic expressions using the Shunting Yard algorithm to parse
    the expression and a stack-based method to evaluate it.
    """

    def __init__(self, expression: str):
        self.expression = expression.replace(" ", "")
        self.pos = 0

    def parse(self):
        """Parse the input expression into Reverse Polish Notation (RPN) using the 
        Shunting Yard algorithm.
        """
        output = []
        operators = []
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

        while self.pos < len(self.expression):
            token = self.next_token()
            if token.isdigit() or '.' in token:
                output.append(float(token))
            elif token in precedence:
                while (operators and operators[-1] != '(' and
                       precedence[operators[-1]] >= precedence[token]):
                    output.append(operators.pop())
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    output.append(operators.pop())
                operators.pop()  # Pop the '('

        while operators:
            output.append(operators.pop())

        return output

    def next_token(self):
        """Retrieve the next token from the expression."""
        token = ''
        while self.pos < len(self.expression) and \
                (self.expression[self.pos].isdigit() or self.expression[self.pos] in '.'):
            token += self.expression[self.pos]
            self.pos += 1
        if token:
            return token
        if self.pos < len(self.expression):
            token = self.expression[self.pos]
            self.pos += 1
            return token
        return ''

    def evaluate_rpn(self, rpn):
        """Evaluate the expression represented in Reverse Polish Notation."""
        stack = []
        for token in rpn:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        return stack[0]


def evaluate(expr: str) -> float:
    """Evaluate an arithmetic expression with +, -, *, /, parentheses, and floating-point numbers."""
    evaluator = ExpressionEvaluator(expr)
    rpn = evaluator.parse()
    return evaluator.evaluate_rpn(rpn)

def evaluate(expr: str) -> float:
    """Evaluate an arithmetic expression using a stack-based approach for parsing 
    and evaluating the expression directly while respecting operator precedence."""

    def apply_operator(operators, values):
        """Applies the operator to the two top values in the values stack."""
        right = values.pop()
        left = values.pop()
        operator = operators.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    def precedence(op):
        """Return the precedence of the operator."""
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def compute(expr):
        """Compute the values from the expression stack."""
        values = []
        operators = []
        i = 0

        while i < len(expr):
            if expr[i] == ' ':
                i += 1
                continue

            if expr[i].isdigit() or expr[i] == '.':
                j = i
                while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):
                    j += 1
                values.append(float(expr[i:j]))
                i = j
            elif expr[i] == '(':
                operators.append(expr[i])
                i += 1
            elif expr[i] == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Remove the '(' from stack
                i += 1
            else:
                while (operators and 
                       precedence(operators[-1]) >= precedence(expr[i])):
                    apply_operator(operators, values)
                operators.append(expr[i])
                i += 1

        while operators:
            apply_operator(operators, values)

        return values[0]

    expr = expr.replace(" ", "")
    return compute(expr)

def evaluate(expr: str) -> float:
    """Evaluate an arithmetic expression using a finite state machine (FSM) approach
    to parse the expression and handle operator precedence directly during evaluation.
    """

    def set_state(char):
        """Set state based on the current character."""
        if char.isdigit() or char == '.':
            return 'NUMBER'
        elif char in '+-*/':
            return 'OPERATOR'
        elif char == '(':
            return 'LPAREN'
        elif char == ')':
            return 'RPAREN'
        return 'INVALID'

    def apply_operation(a, b, op):
        """Apply the operation and return the result."""
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a / b

    def precedence(op):
        """Return the precedence level of the operator."""
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def handle_operator(op):
        """Process an operator based on precedence."""
        while (operators and operators[-1] != '(' and
               precedence(operators[-1]) >= precedence(op)):
            b = values.pop()
            a = values.pop()
            values.append(apply_operation(a, b, operators.pop()))
        operators.append(op)

    values, operators = [], []
    i, n = 0, len(expr)
    current_number = ''

    while i < n:
        char = expr[i]
        state = set_state(char)

        if state == 'NUMBER':
            current_number += char
        else:
            if current_number:
                values.append(float(current_number))
                current_number = ''
            if state == 'OPERATOR':
                handle_operator(char)
            elif state == 'LPAREN':
                operators.append(char)
            elif state == 'RPAREN':
                while operators and operators[-1] != '(':
                    b = values.pop()
                    a = values.pop()
                    values.append(apply_operation(a, b, operators.pop()))
                operators.pop()  # pop the '('

        i += 1

    if current_number:
        values.append(float(current_number))

    while operators:
        b = values.pop()
        a = values.pop()
        values.append(apply_operation(a, b, operators.pop()))

    return values[0]
